import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC06%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E7%AE%A1%E7%90%86%E6%A6%82%E8%AE%BA/","title":"第06章 项目管理概论","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第06章 项目管理概论/README.md"}`),a={name:`README.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="第06章-项目管理概论" tabindex="-1"><a class="header-anchor" href="#第06章-项目管理概论"><span>第06章 项目管理概论</span></a></h1><h2 id="本章概览" tabindex="-1"><a class="header-anchor" href="#本章概览"><span>本章概览</span></a></h2><p>本章介绍项目管理的基本概念、PMBOK知识体系以及项目经理的职责。</p><p><strong>重点知识点：</strong></p><ul><li>项目与项目管理的定义</li><li>PMBOK知识领域</li><li>项目管理过程组</li><li>项目经理的职责和能力</li></ul><hr><h2 id="_6-1-项目概念" tabindex="-1"><a class="header-anchor" href="#_6-1-项目概念"><span>6.1 项目概念</span></a></h2><h3 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h3><p>项目是为创造独特产品、服务或成果而进行的临时性工作。</p><h3 id="项目特征" tabindex="-1"><a class="header-anchor" href="#项目特征"><span>项目特征</span></a></h3><ul><li>临时性</li><li>独特性</li><li>渐进明细</li><li>目标导向</li></ul><h3 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h3><ul><li>项目的特征</li><li>项目与运营的区别</li></ul><h3 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h3><p>临时独特渐进目标，项目特征要记牢</p><hr><h2 id="_6-2-pmbok知识体系" tabindex="-1"><a class="header-anchor" href="#_6-2-pmbok知识体系"><span>6.2 PMBOK知识体系</span></a></h2><h3 id="定义-1" tabindex="-1"><a class="header-anchor" href="#定义-1"><span>定义</span></a></h3><p>PMBOK是项目管理知识体系指南，包含项目管理的核心知识领域。</p><h3 id="十大知识领域" tabindex="-1"><a class="header-anchor" href="#十大知识领域"><span>十大知识领域</span></a></h3><ul><li>整合管理</li><li>范围管理</li><li>进度管理</li><li>成本管理</li><li>质量管理</li><li>资源管理</li><li>沟通管理</li><li>风险管理</li><li>采购管理</li><li>干系人管理</li></ul><h3 id="关键考点-1" tabindex="-1"><a class="header-anchor" href="#关键考点-1"><span>关键考点</span></a></h3><ul><li>PMBOK十大知识领域</li><li>五大过程组</li></ul><h3 id="记忆口诀-1" tabindex="-1"><a class="header-anchor" href="#记忆口诀-1"><span>记忆口诀</span></a></h3><p>整范进成本，质资沟风采干</p><hr><h2 id="_6-3-项目经理职责" tabindex="-1"><a class="header-anchor" href="#_6-3-项目经理职责"><span>6.3 项目经理职责</span></a></h2><h3 id="职责" tabindex="-1"><a class="header-anchor" href="#职责"><span>职责</span></a></h3><ul><li>项目规划</li><li>团队管理</li><li>进度控制</li><li>风险管理</li></ul><h3 id="能力要求" tabindex="-1"><a class="header-anchor" href="#能力要求"><span>能力要求</span></a></h3><ul><li>技术能力</li><li>管理能力</li><li>领导能力</li><li>沟通能力</li></ul><h3 id="关键考点-2" tabindex="-1"><a class="header-anchor" href="#关键考点-2"><span>关键考点</span></a></h3><ul><li>项目经理的主要职责</li><li>项目经理的能力要求</li></ul><h3 id="记忆口诀-2" tabindex="-1"><a class="header-anchor" href="#记忆口诀-2"><span>记忆口诀</span></a></h3><p>规划团队进度风险，项目经理全负责</p>`,35)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};